// The contract between generated code and this runtime, as a counter: a generated file names the
// highest it needs, and a runtime too old for it lacks the constant, so the file fails its
// type-check and its load. gRPC-Go's `SupportPackageIsVersion` counts the same way.

// constants

/**
 * The first contract this runtime supports: the descriptors, the catalogue, the payload codecs and
 * the service layer of `./service`. The counter moves only when generated code needs what the
 * runtime did not have; an older constant stays within a major.
 *
 * @example
 * import { GENERATED_CODE_SUPPORTS_VERSION_1 } from '@francisdesjardins/bead/service';
 *
 * void GENERATED_CODE_SUPPORTS_VERSION_1;
 */
export const GENERATED_CODE_SUPPORTS_VERSION_1 = true;
